import{_ as a,o,c as t,a2 as n}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about Tokeness Base URL, API keys, model names, billing, balance, and tool integrations.","frontmatter":{"title":"FAQ","description":"Frequently asked questions about Tokeness Base URL, API keys, model names, billing, balance, and tool integrations."},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1783490293000}'),s={name:"faq.md"};function i(l,e,r,h,c,d){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="what-is-tokeness" tabindex="-1">What is Tokeness? <a class="header-anchor" href="#what-is-tokeness" aria-label="Permalink to &quot;What is Tokeness?&quot;">​</a></h2><p>Tokeness is an AI API gateway. You use one API key and a unified endpoint to call different AI models, then review balance, logs, and usage in the console.</p><h2 id="what-base-url-should-i-use" tabindex="-1">What Base URL should I use? <a class="header-anchor" href="#what-base-url-should-i-use" aria-label="Permalink to &quot;What Base URL should I use?&quot;">​</a></h2><p>Use the standard OpenAI-compatible Base URL:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://n.tokeness.io/v1</span></span></code></pre></div><p>Do not remove <code>/v1</code> unless a specific client explicitly appends it automatically.</p><h2 id="why-does-authentication-fail" tabindex="-1">Why does authentication fail? <a class="header-anchor" href="#why-does-authentication-fail" aria-label="Permalink to &quot;Why does authentication fail?&quot;">​</a></h2><p>Common causes include incomplete API key copy, missing <code>Bearer</code> prefix, disabled API key, an environment variable that did not take effect, or a tool configured with the wrong provider type.</p><h2 id="why-does-a-request-show-insufficient-balance" tabindex="-1">Why does a request show insufficient balance? <a class="header-anchor" href="#why-does-a-request-show-insufficient-balance" aria-label="Permalink to &quot;Why does a request show insufficient balance?&quot;">​</a></h2><p>Tokeness is prepaid. Check wallet balance and the quota configured on the current API key. If a key has its own limit, the key can be exhausted even when the account still has balance.</p><h2 id="where-should-model-names-be-copied-from" tabindex="-1">Where should model names be copied from? <a class="header-anchor" href="#where-should-model-names-be-copied-from" aria-label="Permalink to &quot;Where should model names be copied from?&quot;">​</a></h2><p>Copy exact model names from the Tokeness console or model marketplace. Do not guess or shorten model IDs.</p><h2 id="where-are-model-prices-authoritative" tabindex="-1">Where are model prices authoritative? <a class="header-anchor" href="#where-are-model-prices-authoritative" aria-label="Permalink to &quot;Where are model prices authoritative?&quot;">​</a></h2><p>Current model prices are authoritative in the Tokeness console model marketplace or in a formal quotation. Documentation avoids fixed price numbers because model availability and upstream costs can change.</p><h2 id="which-tools-can-connect-to-tokeness" tabindex="-1">Which tools can connect to Tokeness? <a class="header-anchor" href="#which-tools-can-connect-to-tokeness" aria-label="Permalink to &quot;Which tools can connect to Tokeness?&quot;">​</a></h2><p>Any tool that supports a custom OpenAI-compatible Base URL can usually connect. See <a href="/integrations/openai-compatible">integration guides</a> for OpenAI SDKs, Claude Code, Cherry Studio, Cline, Roo Code, Continue, Cursor, Dify, n8n, Open WebUI, AnythingLLM, LibreChat, LiteLLM, OpenClaw, and OpenCode.</p>',17)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
